def carry_over_old_entries(apps, schema_editor):
    """A ticked entry was done: verified, by whoever it was assigned to. An
    open one goes back to the pool - its assignee was an ordinary employee,
    who has no way into the new entry screens, so a claim would strand it."""
    BacklogEntry = apps.get_model('backlog', 'BacklogEntry')
    for entry in BacklogEntry.objects.select_related('assigned_to'):
        if entry.is_done:
            entry.status = 'verified'
            entry.entered_by_id = entry.assigned_to.user_id if entry.assigned_to_id else None
        else:
            entry.status = 'pending'
        entry.save(update_fields=['status', 'entered_by'])


